            'Track FX Compressor|Threshold' = @{ Param = 'f:CompThresh'; Min = -40.0; Max = 0.0 }
            'Track FX Compressor|Ratio' = @{ Param = 'f:CompRatio'; Min = 1.0; Max = 12.0 }
