    $tBusFx.Controls.Add($S.BusPresetSpace); $tBusFx.Controls.Add($S.BusPresetLofi); $tBusFx.Controls.Add($S.BusPresetDrive); $tBusFx.Controls.Add($S.BusPresetDub); $tBusFx.Controls.Add($S.BusPresetClear)
