    $S.Play.Add_Click({ try { Start-Studio } catch { Log ('Play failed: ' + $_.Exception.Message); Show-StudioMsg ('Play failed: ' + $_.Exception.Message); Stop-Studio } })
    $S.Stop.Add_Click({ Stop-Studio; Status 'Stopped.' })
