    $S.BtnMidi.Add_Click({
        $d = New-Object Windows.Forms.SaveFileDialog; $d.Filter = 'MIDI file|*.mid'; $d.FileName = 'studio.mid'; $d.InitialDirectory = (Get-StudioDir)
        if ($d.ShowDialog() -eq 'OK') { Sync-Project; [HbStudio.MidiWriter]::Write($S.Proj, $d.FileName); Log "MIDI saved: $($d.FileName)" }
    })
    $S.BtnScd.Add_Click({
        $d = New-Object Windows.Forms.SaveFileDialog; $d.Filter = 'SuperCollider script|*.scd'; $d.FileName = 'studio.scd'; $d.InitialDirectory = (Get-StudioDir)
        if ($d.ShowDialog() -eq 'OK') { Sync-Project; [IO.File]::WriteAllText($d.FileName, (Get-StudioScd $S.Proj $S.ScCode.Text 'live' '' (Join-Path (Get-StudioDir) 'live.stop')), (New-Object Text.UTF8Encoding($false))); Log "Script saved: $($d.FileName)" }
    })
    $S.BtnSave.Add_Click({
        $d = New-Object Windows.Forms.SaveFileDialog; $d.Filter = 'Studio project|*.hbstudio.json'; $d.InitialDirectory = (Join-Path (Get-StudioDir) 'projects'); $d.FileName = 'project.hbstudio.json'
        if ($d.ShowDialog() -eq 'OK') {
            Sync-Project
            $data = Get-StudioProjectData $S.Proj; $data['scCode'] = $S.ScCode.Text
            ($data | ConvertTo-Json -Depth 8) | Set-Content -LiteralPath $d.FileName -Encoding UTF8; $S.Dirty = $false; Log "Saved $($d.FileName)"
        }
    })
    $S.BtnOpen.Add_Click({
        $d = New-Object Windows.Forms.OpenFileDialog; $d.Filter = 'Studio project|*.hbstudio.json;*.json'; $d.InitialDirectory = (Join-Path (Get-StudioDir) 'projects')
        if ($d.ShowDialog() -eq 'OK') {
            try {
                $j = Get-Content -LiteralPath $d.FileName -Raw | ConvertFrom-Json
                Stop-Studio; $S.Proj = Read-StudioProjectData $j; $S.Undo.Clear()
                $S.Loading = $true
                $p = $S.Proj; $S.Bpm.Value = [decimal]$p.Bpm; $S.Bpb.Value = $p.BeatsPerBar; $S.Den.SelectedItem = [string]$p.BeatUnit; $S.Phrase.Value = [decimal][math]::Max(1, [math]::Min(16, $p.PhraseBars)); $S.Bars.Value = $p.Bars; $S.KSwing.Value = [double]($p.Swing * 100)
                $S.KDelay.Value = [double]$p.DelayMix; $S.KBeats.Value = [double]$p.DelayBeats; $S.KFb.Value = [double]$p.DelayFb
                $S.Click.Checked = $p.Click
                $S.Key.SelectedIndex = $p.Key; $S.Scale.SelectedItem = $p.Scale
                if ($j.scCode) { $S.ScCode.Text = [string]$j.scCode }
                $S.Loading = $false
                $S.Roll.Proj = $p; $S.Patch.Proj = $p; Update-PatchSide; Sync-Project; Refresh-Tracks 0; Refresh-SongUi; $S.Patch.FrameAll()
                Log "Opened $($d.FileName)"
            } catch { $S.Loading = $false; Show-StudioMsg ('Could not open: ' + $_.Exception.Message) }
        }
    })
    $S.BtnNew.Add_Click({
        if ($S.Dirty -and [Windows.Forms.MessageBox]::Show('Discard the current project?', 'Audio Studio', 'YesNo', 'Question') -ne 'Yes') { return }
        Stop-Studio; $S.Proj = New-StudioProject; $S.Undo.Clear(); $S.Dirty = $false
        $S.Roll.Proj = $S.Proj; $S.Patch.Proj = $S.Proj; Update-PatchSide; Sync-Project; Refresh-Tracks 0; Refresh-SongUi
    })
    $S.BtnSc.Add_Click({
        $d = New-Object Windows.Forms.OpenFileDialog; $d.Filter = 'sclang.exe|sclang.exe'; $d.Title = 'Locate sclang.exe (SuperCollider install folder)'
        if ($d.ShowDialog() -eq 'OK') { Save-StudioSclangPath $d.FileName; $S.Sc = $d.FileName; Update-ScLabel; Log "SuperCollider set to $($d.FileName)" }
    })
    $S.BtnScGet.Add_Click({ Start-Process 'https://supercollider.github.io/downloads' })
    $S.ScTemplate.Add_Click({
        $S.ScCode.AppendText("`r`nSynthDef(\hello, { |out=0, freq=110, amp=0.3, pan=0, sustain=0.3, cutoff=1800, res=0.5, envamt=1, atk=0.003, rel=0.2, crush=16|`r`n    var env = EnvGen.ar(Env.linen(atk, sustain, rel, 1, -4), doneAction: 2);`r`n    var sig = Mix([Saw.ar(freq), Pulse.ar(freq * 1.005, 0.3)]);`r`n    sig = RLPF.ar(sig, (cutoff * (1 + (EnvGen.ar(Env.perc(0.001, 0.3)) * envamt * 4))).clip(40, 16000), (1 - res).clip(0.05, 1));`r`n    Out.ar(out, Pan2.ar(sig.tanh * env * amp, pan));`r`n}).add;`r`n")
    })
    $S.ScTest.Add_Click({
        if (-not $S.Sc) { Show-StudioMsg 'SuperCollider was not found.'; return }
        $prev = $S.Bars.Value; $S.Engine.SelectedIndex = 1
        Invoke-StudioRender
    })
    $S.ScRecompile.Add_Click({
        Stop-Studio
        if (-not $S.Sc) { Show-StudioMsg 'SuperCollider was not found. Use "Locate SuperCollider" first.'; return }
        if ($S.ScBridgeProc -and -not $S.ScBridgeProc.HasExited -and $S.ScBridgeOsc) {
            Send-StudioScBridge '/hb/transport/stop' | Out-Null
            Start-Sleep -Milliseconds 120
            Send-StudioScBridge '/hb/recompile' | Out-Null
            $S.ScBridgeStatus.Text = 'Live bridge: recompiling definitions...'
            $S.ScSetup.Text = 'Recompile requested; transport left stopped.'
            Log 'SC bridge recompile requested.'
            return
        }
        try {
            Sync-Project
            $r = Write-StudioScSessionFiles $S.Proj
            $outLog = Join-Path $r.Session 'recompile.out.log'
            $errLog = Join-Path $r.Session 'recompile.err.log'
            Remove-Item $outLog, $errLog -Force -ErrorAction SilentlyContinue
            $includeA = '--include-path "' + $r.Library + '"'
            $includeB = '--include-path "' + (Join-Path $r.Session 'classes') + '"'
            $argStr = '-D ' + $includeA + ' ' + $includeB + ' "' + $r.Script + '"'
            $S.ScSetup.Text = 'Compiling SC classes...'
            $p = Start-Process -FilePath $S.Sc -ArgumentList $argStr -WorkingDirectory (Split-Path $S.Sc -Parent) -WindowStyle Hidden -PassThru -Wait -RedirectStandardOutput $outLog -RedirectStandardError $errLog
            if ($p.ExitCode -eq 0) {
                $S.ScSetup.Text = 'SC classes compiled. Session: ' + $r.Session
                Status 'SC definitions compiled; transport left stopped.'
                Log ('SC definitions compiled: ' + $r.Session)
            } else {
                $tail = ''
                if (Test-Path -LiteralPath $errLog) { $tail = ((Get-Content -LiteralPath $errLog -Tail 12 -ErrorAction SilentlyContinue) -join "`r`n") }
                $S.ScSetup.Text = 'SC recompile failed. See recompile.err.log in the session folder.'
                Show-StudioMsg ("SC recompile failed (exit $($p.ExitCode)).`r`n`r`n$tail")
                Log ('SC recompile failed: ' + $tail)
            }
        } catch { $S.ScSetup.Text = 'SC recompile failed: ' + $_.Exception.Message; Log ('SC recompile failed: ' + $_.Exception.Message) }
    })
    $S.ScCheck.Add_Click({
        try {
            $version = 'not found'
            if ($S.Sc) { try { $version = (& $S.Sc -v 2>&1 | Select-Object -First 1) } catch { $version = 'error' } }
            $plugins = Test-StudioScPlugins
            $session = Get-StudioScSessionDir $S.Proj
            $msg = @(
                'SuperCollider: ' + $(if ($S.Sc) { $S.Sc } else { 'not located' }),
                'Version: ' + $version,
                'sc3-plugins: ' + $(if ($plugins) { 'found: ' + $plugins } else { 'not found (required for convolution/spectral effects)' }),
                'Session: ' + $session,
                'Class library: ' + (Get-StudioScLibraryClasses)
            ) -join "`r`n"
            $S.ScSetup.Text = "SC: $version | sc3-plugins: $(if ($plugins) { 'found' } else { 'missing' }) | session: $($S.Proj.ScSessionId)"
            Show-StudioMsg $msg
        } catch { Show-StudioMsg ('SC setup check failed: ' + $_.Exception.Message) }
    })
    $S.ScFolder.Add_Click({
        try { $session = Get-StudioScSessionDir $S.Proj; Start-Process explorer.exe -ArgumentList ('"' + $session + '"') } catch { Log ('Could not open SC session folder: ' + $_.Exception.Message) }
    })
    $S.ScBridgeStart.Add_Click({
        try {
            Stop-Studio
            Start-StudioScBridge | Out-Null
            $S.ScBridgeStatus.Text = $(if ($S.ScBridgeReady) { 'Live bridge: ready.' } else { 'Live bridge: started; waiting for SuperCollider.' })
            $S.ScSetup.Text = 'Live bridge session: ' + (Get-StudioScSessionDir $S.Proj)
            Log 'SC live bridge started.'
        } catch { $S.ScBridgeStatus.Text = 'Live bridge failed: ' + $_.Exception.Message; Log ('SC bridge failed: ' + $_.Exception.Message) }
    })
    $S.ScBridgeStop.Add_Click({
        try { Stop-StudioScBridge; $S.ScBridgeStatus.Text = 'Live bridge: stopped.'; Log 'SC live bridge stopped.' } catch { Log ('SC bridge stop failed: ' + $_.Exception.Message) }
    })
    $S.ScBridgeLoad.Add_Click({
        try {
            if (-not ($S.ScBridgeProc -and -not $S.ScBridgeProc.HasExited)) { Start-StudioScBridge | Out-Null }
            if ($S.ScBridgeProjectPath) {
                Send-StudioScBridge '/hb/project/load' @($S.ScBridgeProjectPath) | Out-Null
                $S.ScBridgeStatus.Text = 'Live bridge: session sent to SuperCollider.'
            }
        } catch { $S.ScBridgeStatus.Text = 'Load failed: ' + $_.Exception.Message; Log ('SC bridge load failed: ' + $_.Exception.Message) }
    })
    $S.ScBridgePlay.Add_Click({
        try {
            if (-not ($S.ScBridgeProc -and -not $S.ScBridgeProc.HasExited)) { Start-StudioScBridge | Out-Null }
            if ($S.ScBridgeProjectPath) { Send-StudioScBridge '/hb/project/load' @($S.ScBridgeProjectPath) | Out-Null; Start-Sleep -Milliseconds 300 }
            Send-StudioScBridge '/hb/transport/play' | Out-Null
            $S.ScBridgeStatus.Text = 'Live bridge: playing.'
        } catch { $S.ScBridgeStatus.Text = 'Play failed: ' + $_.Exception.Message; Log ('SC bridge play failed: ' + $_.Exception.Message) }
    })
    $S.ScBridgeStopPlay.Add_Click({
        try { Send-StudioScBridge '/hb/transport/stop' | Out-Null; $S.ScBridgeStatus.Text = 'Live bridge: stopped (ready).' } catch { }
    })
    $f.Add_FormClosing({ try { Stop-StudioScBridge } catch { } })
    foreach ($k in @('up1', 'dn1', 'up12', 'dn12', 'quant', 'scale', 'rev', 'dbl', 'half', 'all', 'clear', 'undo', 'legato', 'stacc', 'velup', 'veldn', 'velrnd', 'accent', 'inv', 'nudge', 'nudgeb', 'thin', 'octl')) { $S["T_$k"].Add_Click({ param($snd, $e) Invoke-StudioTool ([string]$snd.Tag) }) }
    $S.T_hum.Add_Click({ Invoke-StudioTool 'hum' }); $S.T_mut.Add_Click({ Invoke-StudioTool 'mut' }); $S.T_chop.Add_Click({ Invoke-StudioTool 'chop' }); $S.T_ratch.Add_Click({ Invoke-StudioTool 'ratch' })
    $S.T_euc.Add_Click({ Invoke-StudioGenerator 'euc' }); $S.T_walk.Add_Click({ Invoke-StudioGenerator 'walk' }); $S.T_poly.Add_Click({ Invoke-StudioGenerator 'poly' })
    function Set-RollZoom([double]$f) { $S.Roll.Zoom = [math]::Max(3.0, [math]::Min(400.0, $S.Roll.Zoom * $f)); $S.Roll.UpdateScroll(); $S.Roll.Invalidate() }
    $S.T_zoomIn.Add_Click({ Set-RollZoom 1.3 }); $S.T_zoomOut.Add_Click({ Set-RollZoom (1.0 / 1.3) })
    $S.AiCompose.Add_Click({ Invoke-AiAction 'compose' }); $S.AiVary.Add_Click({ Invoke-AiAction 'vary' }); $S.AiSynth.Add_Click({ Invoke-AiAction 'synth' }); $S.AiAdvice.Add_Click({ Invoke-AiAction 'advice' })
    $S.AiRefresh.Add_Click({ Update-AiModels })
    $f.Add_FormClosing({
        if ($S.Dirty -and [Windows.Forms.MessageBox]::Show('Close the Studio? Unsaved changes will be lost.', 'Audio Studio', 'YesNo', 'Question') -ne 'Yes') { $_.Cancel = $true; return }
        $timer.Stop(); Stop-Studio
    })
    $f.Add_Shown({ Sync-Project; Refresh-Tracks 0; Refresh-SongUi; Update-FfmpegLabel; Update-ScLabel; Update-AiModels; $S.Roll.UpdateScroll(); $S.Roll.ScrollToPitch(48); $S.Roll.Focus(); Status 'Ready. Space = play/stop; Roll: click add, drag edge = length, right-click erase, double-click the ruler to sketch arrangement markers; Drums: C2 kick, D2 snare, D#2 clap, F#2 hat, A#2 open hat.'; $S.Dirty = $false })

